    assertQty(qty);
    const key = skuKey(sku);
    return this.#locks.run([key], async () => {
      const item = (await this.store.get(key)) || { stock: 0, reserved: 0, sold: 0 };
      item.stock += qty;
      await this.store.set(key, item);
      return { sku, ...item };
    });
  }

